import {
  CallHandler,
  ExecutionContext,
  HttpException,
  Injectable,
  Logger,
  NestInterceptor,
} from '@nestjs/common';
import { Request, Response } from 'express';
import { Observable, catchError, tap, throwError } from 'rxjs';

interface HttpRequest extends Request {
  id?: string;
}

/**
 * Logs request metadata only. Bodies and query strings are never logged,
 * because they carry the health profile (allergies, blood pressure, goals),
 * which is GDPR Art. 9 special-category data.
 */
@Injectable()
export class RequestLoggingInterceptor implements NestInterceptor {
  private readonly logger = new Logger('HttpRequest');

  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const http = context.switchToHttp();
    const request = http.getRequest<HttpRequest>();
    const response = http.getResponse<Response>();
    const startedAt = Date.now();

    return next.handle().pipe(
      tap(() => {
        this.logRequest({
          request,
          statusCode: response.statusCode,
          durationMs: Date.now() - startedAt,
        });
      }),
      catchError((error: unknown) => {
        this.logRequest({
          request,
          statusCode: error instanceof HttpException ? error.getStatus() : 500,
          durationMs: Date.now() - startedAt,
          error: error instanceof Error ? error.name : 'UnknownError',
        });
        return throwError(() => error);
      }),
    );
  }

  private logRequest({
    request,
    statusCode,
    durationMs,
    error,
  }: {
    request: HttpRequest;
    statusCode: number;
    durationMs: number;
    error?: string;
  }): void {
    const entry = {
      requestId: request.id,
      method: request.method,
      path: (request.originalUrl || request.url).split('?')[0],
      statusCode,
      durationMs,
      ...(error ? { error } : {}),
    };

    this.logger[error ? 'error' : 'log'](JSON.stringify(entry));
  }
}

import { BadRequestException, CallHandler, ExecutionContext, Logger } from '@nestjs/common';
import { lastValueFrom, of, throwError } from 'rxjs';
import { RequestLoggingInterceptor } from './request-logging.interceptor';

const profile = {
  allergies: ['peanuts'],
  bloodPressure: 'high',
  goals: ['lose weight'],
};

function contextFor(url: string, statusCode = 201): ExecutionContext {
  const request = { method: 'POST', originalUrl: url, body: { profile } };
  const response = { statusCode };
  return {
    switchToHttp: () => ({
      getRequest: () => request,
      getResponse: () => response,
    }),
  } as unknown as ExecutionContext;
}

describe('RequestLoggingInterceptor', () => {
  let log: jest.SpyInstance;
  let error: jest.SpyInstance;

  beforeEach(() => {
    log = jest.spyOn(Logger.prototype, 'log').mockImplementation();
    error = jest.spyOn(Logger.prototype, 'error').mockImplementation();
  });

  afterEach(() => jest.restoreAllMocks());

  it('logs metadata only, never bodies or query strings', async () => {
    const next: CallHandler = { handle: () => of({ profile, items: [] }) };

    await lastValueFrom(
      new RequestLoggingInterceptor().intercept(
        contextFor('/api/meal-plan?allergy=peanuts'),
        next,
      ),
    );

    const line = log.mock.calls[0][0] as string;
    expect(JSON.parse(line)).toEqual({
      method: 'POST',
      path: '/api/meal-plan',
      statusCode: 201,
      durationMs: expect.any(Number),
    });
    expect(line).not.toMatch(/peanuts|bloodPressure|allergies|high/);
  });

  it('logs the error status and name without the message', async () => {
    const next: CallHandler = {
      handle: () =>
        throwError(() => new BadRequestException('allergies: peanuts invalid')),
    };

    await expect(
      lastValueFrom(
        new RequestLoggingInterceptor().intercept(contextFor('/api/meal-plan'), next),
      ),
    ).rejects.toThrow(BadRequestException);

    const line = error.mock.calls[0][0] as string;
    expect(JSON.parse(line)).toMatchObject({
      statusCode: 400,
      error: 'BadRequestException',
    });
    expect(line).not.toMatch(/peanuts/);
  });
});

