     1	import { Injectable, Logger } from '@nestjs/common';
     2	import * as fs from 'fs';
     3	import * as path from 'path';
     4	import { ANALYSIS_SCHEMA_VERSION, VideoAnalysis } from './analyzers/analysis.schema';
     5	
     6	const SEED_FILE = path.join(process.cwd(), 'data', 'videos.seed.json');
     7	const DEFAULT_TTL_MS = 30 * 24 * 60 * 60 * 1000; // 30 days
     8	
     9	function sanitize(str: string): string {
    10	  return str.replace(/[^a-zA-Z0-9_-]/g, '_');
    11	}
    12	
    13	@Injectable()
    14	export class TranscriptCacheService {
    15	  private readonly logger = new Logger(TranscriptCacheService.name);
    16	  private readonly memory = new Map<string, VideoAnalysis>();
    17	
    18	  cacheDir(): string {
    19	    const dir =
    20	      process.env.MEALPILOT_CACHE_DIR || path.join(process.cwd(), 'data', 'cache');
    21	    fs.mkdirSync(dir, { recursive: true });
    22	    return dir;
    23	  }
    24	
    25	  private keyFor(
    26	    videoId: string,
    27	    provider: string,
    28	    model: string,
    29	    version = ANALYSIS_SCHEMA_VERSION,
    30	  ): string {
    31	    return `${videoId}.${provider}.${sanitize(model)}.v${version}`;
    32	  }
    33	
    34	  private fileFor(
    35	    videoId: string,
    36	    provider: string,
    37	    model: string,
    38	    version = ANALYSIS_SCHEMA_VERSION,
    39	  ): string {
    40	    return path.join(
    41	      this.cacheDir(),
    42	      `${this.keyFor(videoId, provider, model, version)}.json`,
    43	    );
    44	  }
    45	
    46	  private isExpired(entry: VideoAnalysis, ttlMs = DEFAULT_TTL_MS): boolean {
    47	    if (!entry.analyzedAt) return true;
    48	    const time = new Date(entry.analyzedAt).getTime();
    49	    if (isNaN(time)) return true;
    50	    return Date.now() - time > ttlMs;
    51	  }
    52	
    53	  get(
    54	    videoId: string,
    55	    provider: 'gemini' | 'mock' = 'gemini',
    56	    model = 'gemini-3.8-flash',
    57	  ): VideoAnalysis | null {
    58	    const cacheKey = this.keyFor(videoId, provider, model);
    59	    if (this.memory.has(cacheKey)) {
    60	      const memEntry = this.memory.get(cacheKey)!;
    61	      if (this.isExpired(memEntry)) {
    62	        this.memory.delete(cacheKey);
    63	        return null;
    64	      }
    65	      return memEntry;
    66	    }
    67	
    68	    const filePath = this.fileFor(videoId, provider, model);
    69	    if (fs.existsSync(filePath)) {
    70	      try {
    71	        const parsed = JSON.parse(
    72	          fs.readFileSync(filePath, 'utf8'),
    73	        ) as VideoAnalysis;
    74	
    75	        if (parsed.schemaVersion !== ANALYSIS_SCHEMA_VERSION) {
    76	          return null;
    77	        }
    78	
    79	        if (this.isExpired(parsed)) {
    80	          this.logger.debug(`Cache expired for ${cacheKey}`);
    81	          try {
    82	            fs.unlinkSync(filePath);
    83	          } catch {
    84	            // ignore
    85	          }
    86	          return null;
    87	        }
    88	
    89	        this.memory.set(cacheKey, parsed);
    90	        return parsed;
    91	      } catch (err) {
    92	        this.logger.warn(`Ignoring corrupt cache file ${filePath}: ${err}`);
    93	        return null;
    94	      }
    95	    }
    96	
    97	    return null;
    98	  }
    99	
   100	  set(entry: VideoAnalysis, currentSystemMode?: 'live' | 'mock'): VideoAnalysis {
   101	    // Never persist unavailable results
   102	    if (entry.status === 'unavailable') {
   103	      return entry;
   104	    }
   105	
   106	    // Never persist mock results while in live mode
   107	    if (currentSystemMode === 'live' && entry.provider === 'mock') {
   108	      return entry;
   109	    }
   110	
   111	    const cacheKey = this.keyFor(
   112	      entry.videoId,
   113	      entry.provider,
   114	      entry.model,
   115	      entry.schemaVersion || ANALYSIS_SCHEMA_VERSION,
   116	    );
   117	
   118	    this.memory.set(cacheKey, entry);
   119	
   120	    try {
   121	      const filePath = this.fileFor(
   122	        entry.videoId,
   123	        entry.provider,
   124	        entry.model,
   125	        entry.schemaVersion || ANALYSIS_SCHEMA_VERSION,
   126	      );
   127	      fs.writeFileSync(filePath, JSON.stringify(entry, null, 2));
   128	    } catch (err) {
   129	      this.logger.warn(`Could not persist cache for ${entry.videoId}: ${err}`);
   130	    }
   131	
   132	    return entry;
   133	  }
   134	
   135	  list(): VideoAnalysis[] {
   136	    const dir = this.cacheDir();
   137	    const versionPattern = new RegExp(`\\.v${ANALYSIS_SCHEMA_VERSION}\\.json$`);
   138	    const files = fs.existsSync(dir)
   139	      ? fs.readdirSync(dir).filter((f) => versionPattern.test(f))
   140	      : [];
   141	
   142	    const out: VideoAnalysis[] = [];
   143	    for (const f of files) {
   144	      try {
   145	        const parsed = JSON.parse(
   146	          fs.readFileSync(path.join(dir, f), 'utf8'),
   147	        ) as VideoAnalysis;
   148	        if (!this.isExpired(parsed)) {
   149	          out.push(parsed);
   150	        }
   151	      } catch {
   152	        // skip corrupt files
   153	      }
   154	    }
   155	
   156	    for (const [, entry] of this.memory) {
   157	      if (
   158	        !this.isExpired(entry) &&
   159	        !out.find((e) => e.videoId === entry.videoId && e.provider === entry.provider)
   160	      ) {
   161	        out.push(entry);
   162	      }
   163	    }
   164	
   165	    return out;
   166	  }
   167	
   168	  clear(videoId?: string): { cleared: number } {
   169	    const dir = this.cacheDir();
   170	    if (videoId) {
   171	      let count = 0;
   172	      for (const [key] of this.memory) {
   173	        if (key.startsWith(`${videoId}.`)) {
   174	          this.memory.delete(key);
   175	        }
   176	      }
   177	      if (fs.existsSync(dir)) {
   178	        for (const f of fs.readdirSync(dir)) {
   179	          if (f.startsWith(`${videoId}.`)) {
   180	            try {
   181	              fs.unlinkSync(path.join(dir, f));
   182	              count++;
   183	            } catch {
   184	              // ignore
   185	            }
   186	          }
   187	        }
   188	      }
   189	      return { cleared: count || 1 };
   190	    }
   191	
   192	    const n = this.list().length;
   193	    this.memory.clear();
   194	    if (fs.existsSync(dir)) {
   195	      for (const f of fs.readdirSync(dir).filter((f) => f.endsWith('.json'))) {
   196	        try {
   197	          fs.unlinkSync(path.join(dir, f));
   198	        } catch {
   199	          // ignore
   200	        }
   201	      }
   202	    }
   203	    return { cleared: n };
   204	  }
   205	
   206	  loadSeed(): Array<{ videoId: string; title: string; channel: string }> {
   207	    try {
   208	      if (!fs.existsSync(SEED_FILE)) return [];
   209	      const parsed = JSON.parse(fs.readFileSync(SEED_FILE, 'utf8'));
   210	      return Array.isArray(parsed) ? parsed : parsed.videos ?? [];
   211	    } catch {
   212	      return [];
   213	    }
   214	  }
   215	}
