    15	export interface AnalysisResultWithCacheMeta {
    16	  analysis: VideoAnalysis;
    17	  fromCache: boolean;
    18	}
    19	
    20	@Injectable()
    21	export class VideoAnalysisService {
    22	  private readonly logger = new Logger(VideoAnalysisService.name);
    23	
    24	  constructor(
    25	    private readonly cache: TranscriptCacheService,
    26	    @Inject(VIDEO_ANALYZER) private readonly analyzer: VideoAnalyzer,
    27	    private readonly config: AppConfigService,
    28	    @Inject(YOUTUBE_SERVICE) private readonly youtube: IYouTubeService,
    29	  ) {}
    30	
    31	  async analyzeWithMeta(
    32	    target: VideoTarget,
    33	  ): Promise<AnalysisResultWithCacheMeta> {
    34	    const cached = this.cache.get(
    35	      target.videoId,
    36	      this.analyzer.provider(),
    37	      this.analyzer.model(),
    38	    );
    39	    if (cached) {
    40	      return { analysis: cached, fromCache: true };
    41	    }
    42	
    43	    const enriched = await this.withDetails(target);
    44	    const result = await this.analyzer.analyze(enriched);
    45	    if (result.status === 'ok') {
    46	      this.cache.set(result, this.config.effectiveLlmMode);
    47	    }
    48	
    49	    return { analysis: result, fromCache: false };
    50	  }
    51	
    52	  async analyze(target: VideoTarget): Promise<VideoAnalysis> {
    53	    const { analysis } = await this.analyzeWithMeta(target);
    54	    return analysis;
    55	  }
    56	
    57	  provider(): 'gemini' | 'mock' {
    58	    return this.analyzer.provider();
    59	  }
    60	
    61	  model(): string {
    62	    return this.analyzer.model();
    63	  }
    64	
    65	  /**
    66	   * Fetch the description (and real title/channel) when the caller does not
    67	   * have it. Costs 1 YouTube quota unit and runs only on a cache miss.
    68	   */
    69	  private async withDetails(target: VideoTarget): Promise<VideoTarget> {
    70	    if (target.description !== undefined) return target;
    71	    try {
    72	      const [details] = await this.youtube.getDetails([target.videoId]);
    73	      if (!details) return target;
    74	      return {
    75	        videoId: target.videoId,
    76	        title: details.title || target.title,
    77	        channel: details.channel || target.channel,
    78	        channelId: details.channelId || target.channelId,
    79	        description: details.description,
    80	      };
    81	    } catch (err) {
    82	      this.logger.warn(
    83	        `Could not fetch details for ${target.videoId}; analyzing without description: ${err}`,
    84	      );
    85	      return target;
    86	    }
    87	  }
    88	}
