    12	  AGENT_TIMEOUT_MS: z.coerce.number().int().positive().default(90000),
    13	  ANALYSIS_CONCURRENCY: z.coerce.number().int().positive().default(3),
    14	  MEALPILOT_CACHE_DIR: z.string().default(''),
    15	  TRUSTED_CHANNELS_FILE: z.string().default(''),
    16	});
    17	
    18	export type RawAppConfig = z.infer<typeof configSchema>;
    19	
    20	export interface AppConfig extends RawAppConfig {
    21	  effectiveLlmMode: 'live' | 'mock';
    22	}
