    24	export function validateConfig(config: Record<string, unknown>): AppConfig {
    25	  const merged = { ...config, ...process.env };
    26	  const parsed = configSchema.safeParse(merged);
    27	  if (!parsed.success) {
    28	    throw new Error(`Configuration validation error: ${parsed.error.message}`);
    29	  }
    30	
    31	  const values = parsed.data;
    32	
    33	  if (values.MEALPILOT_LLM_MODE === 'live' && !values.GEMINI_API_KEY) {
    34	    throw new Error(
    35	      'GEMINI_API_KEY is required when MEALPILOT_LLM_MODE is set to "live"',
    36	    );
    37	  }
    38	
    39	  let effectiveLlmMode: 'live' | 'mock';
    40	  if (values.MEALPILOT_LLM_MODE === 'live') {
    41	    effectiveLlmMode = 'live';
    42	  } else if (values.MEALPILOT_LLM_MODE === 'mock') {
    43	    effectiveLlmMode = 'mock';
    44	  } else {
    45	    effectiveLlmMode = values.GEMINI_API_KEY ? 'live' : 'mock';
    46	  }
    47	
    48	  return {
    49	    ...values,
    50	    effectiveLlmMode,
    51	  };
    52	}
