     1	import { Unit } from '../videos/analyzers/analysis.schema';
     2	
     3	export type BaseUnit = 'g' | 'ml' | CountUnit;
     4	export type CountUnit = 'piece' | 'can' | 'clove' | 'slice' | 'bunch';
     5	
     6	const MASS: Partial<Record<Unit, number>> = { g: 1, kg: 1000 };
     7	const VOLUME: Partial<Record<Unit, number>> = { ml: 1, l: 1000, tsp: 5, tbsp: 15, cup: 240 };
     8	const COUNT = new Set<Unit>(['piece', 'can', 'clove', 'slice', 'bunch']);
     9	
    10	/** g per ml, only for ingredients where the conversion is reliable. */
    11	const DENSITY: Array<[RegExp, number]> = [
    12	  [/\b(water|stock|broth)\b/, 1],
    13	  [/\bmilk\b/, 1.03],
    14	  [/\boil\b/, 0.92],
    15	  [/\bflour\b/, 0.53],
    16	  [/\bsugar\b/, 0.85],
    17	  [/\brice\b/, 0.85],
    18	];
    19	
    20	export function densityFor(name: string): number | null {
    21	  for (const [pattern, density] of DENSITY) {
    22	    if (pattern.test(name)) return density;
    23	  }
    24	  return null;
    25	}
    26	
    27	export interface BaseAmount {
    28	  amount: number;
    29	  unit: BaseUnit;
    30	}
    31	
    32	/** Converts to g, ml or a count. Returns null for pinch or unknown units. */
    33	export function toBaseUnit(quantity: number, unit: Unit): BaseAmount | null {
    34	  if (MASS[unit] !== undefined) return { amount: quantity * MASS[unit]!, unit: 'g' };
    35	  if (VOLUME[unit] !== undefined) return { amount: quantity * VOLUME[unit]!, unit: 'ml' };
    36	  if (COUNT.has(unit)) return { amount: quantity, unit: unit as CountUnit };
    37	  return null;
    38	}
    39	
    40	/** Rough grams for ranking ingredients by importance (not for nutrition). */
    41	const COUNT_GRAMS: Record<CountUnit, number> = { can: 400, piece: 120, bunch: 100, slice: 30, clove: 5 };
    42	
    43	export function approximateGrams(quantity: number | null, unit: Unit | null, name: string): number {
    44	  if (quantity === null || unit === null) return 0;
    45	  const base = toBaseUnit(quantity, unit);
    46	  if (!base) return 0;
    47	  if (base.unit === 'g') return base.amount;
    48	  if (base.unit === 'ml') return base.amount * (densityFor(name) ?? 1);
    49	  return base.amount * COUNT_GRAMS[base.unit];
    50	}
    51	
    52	/**
    53	 * Rounds up to something you can buy or measure: 380 g -> 400 g,
    54	 * 1.3 cans -> 2 cans, 12 ml -> 15 ml.
    55	 */
    56	export function roundToBuyingUnit(amount: number, unit: BaseUnit): number {
    57	  if (unit === 'g' || unit === 'ml') {
    58	    const step = amount < 20 ? 5 : amount < 100 ? 10 : amount < 1000 ? 50 : 100;
    59	    return Math.ceil(amount / step - 1e-9) * step;
    60	  }
    61	  return Math.ceil(amount - 1e-9);
    62	}
    63	
    64	export function formatAmount(amount: number, unit: BaseUnit): { amount: number; unit: string } {
    65	  if (unit === 'g' && amount >= 1000) return { amount: amount / 1000, unit: 'kg' };
    66	  if (unit === 'ml' && amount >= 1000) return { amount: amount / 1000, unit: 'l' };
    67	  return { amount, unit };
    68	}
