    44	  'optional',
    45	  'to',
    46	  'taste',
    47	  'of',
    48	]);
    49	
    50	const KEEP_PLURAL = new Set(['hummus', 'couscous', 'asparagus', 'molasses', 'swiss', 'grass', 'oats', 'lemongrass']);
    51	
    52	export function singularize(word: string): string {
    53	  if (KEEP_PLURAL.has(word) || word.length <= 3) return word;
    54	  if (word.endsWith('ies')) return `${word.slice(0, -3)}y`;
    55	  if (word.endsWith('oes')) return word.slice(0, -2);
    56	  if (/(ches|shes|sses|xes)$/.test(word)) return word.slice(0, -2);
    57	  if (word.endsWith('s') && !word.endsWith('ss') && !word.endsWith('us')) return word.slice(0, -1);
    58	  return word;
    59	}
    60	
    61	export function normalizeIngredientName(name: string): string {
    62	  const words = name
    63	    .toLowerCase()
    64	    .replace(/\([^)]*\)/g, ' ')
    65	    .replace(/[^a-z0-9\s-]/g, ' ')
    66	    .split(/\s+/)
    67	    .filter((w) => w && !DESCRIPTORS.has(w));
    68	  if (words.length === 0) return name.toLowerCase().trim();
    69	  words[words.length - 1] = singularize(words[words.length - 1]);
    70	  const joined = words.join(' ');
    71	  return ALIASES[joined] ?? joined;
    72	}
