    41	/**
    42	 * Compact, size-capped view of an analysis for the agent's context window.
    43	 * Every string comes from the video or its description, so it is untrusted:
    44	 * control characters are stripped and each field is length-capped. Digests
    45	 * belong in tool results only, never in the system prompt.
    46	 */
    47	export function buildDigest(analysis: VideoAnalysis, ctx: DigestContext): VideoDigest {
    48	  const clean = (s: string | undefined, max: number) => sanitizeUntrusted(s, max);
    49	  const ordered = byWeight(analysis.ingredients ?? []);
    50	
    51	  const digest: VideoDigest = {
    52	    videoId: analysis.videoId,
    53	    title: clean(analysis.title, 120),
    54	    channel: clean(analysis.channel, 60),
    55	    trustedChannel: ctx.trusted,
    56	    recipeName: clean(analysis.recipeName, 100),
    57	    mainProtein: analysis.mainProtein,
    58	    cuisine: analysis.cuisine ? clean(analysis.cuisine, 30) : undefined,
    59	    mealType: analysis.mealType ?? [],
    60	    prepMinutes: analysis.prepMinutes ?? null,
    61	    servings: analysis.servings ?? null,
    62	    coverage: analysis.coverage,
    63	    keyIngredients: ordered.filter((i) => !isUnclear(i)).slice(0, 10).map(formatIngredient),
    64	    lowConfidenceIngredients: ordered.filter(isUnclear).slice(0, 5).map(formatIngredient),
    65	    restrictionTags: analysis.restrictionTags ?? [],
    66	    estimatedSignals: analysis.nutritionSignals ?? [],
    67	    matchedGoals: matchGoals(analysis, ctx.healthGoals).matched,
    68	    labelCheck: (analysis.labelCheck ?? []).slice(0, 5).map((l) => clean(l, 40)),
    69	    allergySafety: { status: ctx.verdict.status, notes: clean(ctx.verdict.notes, 300) },
    70	    fitsTime: checkTime(analysis, ctx.maxCookMinutes).fitsTime,
    71	    ...(ctx.score !== undefined ? { score: ctx.score } : {}),
    72	  };
    73	  return shrinkToFit(digest);
    74	}
