    76	function size(d: VideoDigest): number {
    77	  return Buffer.byteLength(JSON.stringify(d), 'utf8');
    78	}
    79	
    80	/** Drops the least important detail first until the digest fits. */
    81	function shrinkToFit(d: VideoDigest): VideoDigest {
    82	  const steps: Array<(x: VideoDigest) => void> = [
    83	    (x) => (x.lowConfidenceIngredients = x.lowConfidenceIngredients.slice(0, 2)),
    84	    (x) => (x.keyIngredients = x.keyIngredients.slice(0, 6)),
    85	    (x) => (x.allergySafety.notes = sanitizeUntrusted(x.allergySafety.notes, 150)),
    86	    (x) => (x.labelCheck = x.labelCheck.slice(0, 2)),
    87	    (x) => (x.lowConfidenceIngredients = []),
    88	    (x) => (x.keyIngredients = x.keyIngredients.slice(0, 3)),
    89	    (x) => (x.title = sanitizeUntrusted(x.title, 60)),
    90	  ];
    91	  for (const step of steps) {
    92	    if (size(d) <= MAX_DIGEST_BYTES) break;
    93	    step(d);
    94	  }
    95	  return d;
    96	}
