    16	/**
    17	 * Which analysis signals or tags count as evidence for a goal. Until
    18	 * nutrients are computed from a food database these are model estimates.
    19	 * Goals with no entry cannot be verified from the analysis yet.
    20	 */
    21	const GOAL_EVIDENCE: Record<HealthGoal, string[]> = {
    22	  'high-protein': ['high-protein'],
    23	  'low-sodium': ['low-sodium'],
    24	  'high-fiber': ['high-fiber'],
    25	  'low-carb': ['low-carb'],
    26	  'low-sugar': [],
    27	  'weight-loss': [],
    28	};
    29	
    30	export interface GoalMatch {
    31	  matched: HealthGoal[];
    32	  missing: HealthGoal[];
    33	  /** Goals the current analysis cannot speak to (no signal exists yet). */
    34	  unverifiable: HealthGoal[];
    35	}
    36	
    37	export function matchGoals(
    38	  analysis: Pick<VideoAnalysis, 'nutritionSignals' | 'restrictionTags'>,
    39	  goals: readonly HealthGoal[] | undefined,
    40	): GoalMatch {
    41	  const evidence = new Set<string>([
    42	    ...(analysis.nutritionSignals ?? []),
    43	    ...(analysis.restrictionTags ?? []),
    44	  ]);
    45	  const result: GoalMatch = { matched: [], missing: [], unverifiable: [] };
    46	  for (const goal of goals ?? []) {
    47	    const signals = GOAL_EVIDENCE[goal];
    48	    if (signals.length === 0) result.unverifiable.push(goal);
    49	    else if (signals.some((s) => evidence.has(s))) result.matched.push(goal);
    50	    else result.missing.push(goal);
    51	  }
    52	  return result;
    53	}
