   119	        const time = checkTime(analyzed, dto.maxCookMinutes);
   120	        if (time.fitsTime === false) {
   121	          excluded.push(excludedVideo(c.videoId, analyzed.title, 'too_long', time.note!));
   122	          continue;
   123	        }
   124	
   125	        eligible.push({ analysis: analyzed, verdict });
   126	      }
   127	    }
   128	
   129	    const isTrusted = (id: string | undefined) => this.trustedChannels.isTrusted(id);
   130	    const ranked = selectRanked(
   131	      eligible.map((e) => e.analysis),
   132	      { restrictions: dto.restrictions, healthGoals: dto.healthGoals, maxCookMinutes: dto.maxCookMinutes, isTrusted },
   133	      max,
   134	    );
   135	
   136	    const recommendations: RecommendationDto[] = ranked.map(({ analysis: analyzed }) => {
   137	      const verdict = eligible.find((e) => e.analysis === analyzed)!.verdict;
   138	      const time = checkTime(analyzed, dto.maxCookMinutes);
   139	      const goals = matchGoals(analyzed, dto.healthGoals);
   140	      const matchedTags = [
   141	        ...new Set([...this.matchTags(analyzed, restrictions, healthText), ...goals.matched]),
   142	      ];
   143	      return buildRecommendation({
   144	        analysis: analyzed,
   145	        verdict,
   146	        whyItFits: this.explainFit(analyzed, restrictions, dto, matchedTags),
   147	        matchedTags,
   148	        healthNotes: [
   149	          this.healthNotes(analyzed, dto),
   150	          time.note,
   151	          goals.unverifiable.length
   152	            ? `Goals not yet checkable from the recipe: ${goals.unverifiable.join(', ')}.`
   153	            : undefined,
   154	        ]
   155	          .filter(Boolean)
   156	          .join(' '),
   157	        request: dto,
   158	        trusted: isTrusted(analyzed.channelId),
   159	      });
   160	    });
   161	
   162	    const meta: MealPlanMetaDto = {
   163	      mode: this.config.effectiveLlmMode,
   164	      provider: this.analysis.provider(),
   165	      model: this.analysis.model(),
   166	      analyzed: analyzedCount,
   167	      fromCache: fromCacheCount,
   168	      failures,
   169	    };
   170	
   171	    return {
   172	      recommendations,
   173	      excluded,
   174	      disclaimer: MEDICAL_DISCLAIMER,
   175	      shoppingList: buildShoppingList(
   176	        ranked.map((r) => ({ analysis: r.analysis })),
   177	        dto.householdSize ?? 1,
   178	      ),
   179	      meta,
   180	    };
   181	  }
