   191	  /**
   192	   * ALLERGY SAFETY (table-driven safety rules):
   193	   * 1. If analysis is unavailable -> uncertain (excluded from recommendations).
   194	   * 2. Any matching allergen with confirmed or likely confidence -> unsafe.
   195	   * 3. Matching allergen with possible confidence, or matched in crossContactNotes -> uncertain.
   196	   * 4. Alias hit in ingredients or steps text -> unsafe.
   197	   * 5. coverage: partial and user has severe allergies -> uncertain.
   198	   * 6. Offline mock analysis cannot prove absence of severe allergens -> uncertain.
   199	   * 7. Otherwise -> safe (with "verify recipe" note).
   200	   */
   201	  evaluateAllergySafety(
   202	    analyzed: Partial<VideoAnalysis> & {
   203	      ingredients?: Array<string | { name: string; rawText?: string }>;
   204	      detectedAllergens?: string[];
   205	      transcript?: string;
   206	    },
   207	    allergies: string[],
   208	  ): { status: 'safe' | 'uncertain' | 'unsafe'; notes: string } {
   209	    if (analyzed.status === 'unavailable') {
   210	      return {
   211	        status: 'uncertain',
   212	        notes: `Analysis unavailable (${analyzed.error || 'unprocessed'}). Excluded as uncertain to prevent unsafe assumptions.`,
   213	      };
   214	    }
   215	
   216	    if (!allergies.length) {
   217	      return {
   218	        status: 'safe',
   219	        notes: 'No allergies declared; always verify ingredients yourself.',
   220	      };
   221	    }
   222	
   223	    // Map user allergies to canonical EU 14 allergens
   224	    const userCanonical = new Set<string>();
   225	    for (const a of allergies) {
   226	      for (const c of mapToCanonicalAllergens(a)) {
   227	        userCanonical.add(c);
   228	      }
   229	    }
   230	
   231	    // 2 & 3: Check structured allergen evidence
   232	    if (analyzed.allergens && analyzed.allergens.length > 0) {
   233	      for (const evidence of analyzed.allergens) {
   234	        const isMatched =
   235	          userCanonical.has(evidence.allergen) ||
   236	          allergies.some((a) => haystackMatchesAllergy(evidence.allergen, a));
   237	
   238	        if (isMatched) {
   239	          if (
   240	            evidence.confidence === 'confirmed' ||
   241	            evidence.confidence === 'likely'
   242	          ) {
   243	            return {
   244	              status: 'unsafe',
   245	              notes: `Detected allergen ${evidence.allergen} (${evidence.confidence}): ${evidence.evidence}. Do not use this recipe.`,
   246	            };
   247	          }
   248	          if (evidence.confidence === 'possible') {
   249	            return {
   250	              status: 'uncertain',
   251	              notes: `Possible allergen ${evidence.allergen}: ${evidence.evidence}. Excluded as uncertain.`,
   252	            };
   253	          }
   254	        }
   255	      }
   256	    }
   257	
   258	    // 3: Check cross-contact notes
   259	    if (analyzed.crossContactNotes && analyzed.crossContactNotes.length > 0) {
   260	      for (const note of analyzed.crossContactNotes) {
   261	        const crossMatches = findAllergyMatches(note, allergies);
   262	        if (crossMatches.length > 0) {
   263	          return {
   264	            status: 'uncertain',
   265	            notes: `Cross-contact risk noted for ${crossMatches.join(', ')}: "${note}". Excluded as uncertain.`,
   266	          };
   267	        }
   268	      }
   269	    }
   270	
   271	    // 4: Direct alias check in ingredients (normalised name and raw text as
   272	    // said or written, e.g. "peanut satay sauce") and steps
   273	    const rawIngredients = (analyzed.ingredients ?? [])
   274	      .map((i) => (typeof i === 'string' ? i : `${i.name} ${i.rawText ?? ''}`))
   275	      .join(' ; ');
   276	    const rawSteps = (analyzed.steps ?? []).join(' ');
   277	    const detectedAllergensHay = (analyzed.detectedAllergens ?? []).join(' ');
   278	
   279	    const directMatches = findAllergyMatches(
   280	      `${rawIngredients} ${rawSteps} ${detectedAllergensHay}`,
   281	      allergies,
   282	    );
   283	    if (directMatches.length > 0) {
   284	      return {
   285	        status: 'unsafe',
   286	        notes: `Detected allergen match (${directMatches.join(', ')}) in analyzed ingredients/steps. Do not use this recipe.`,
   287	      };
   288	    }
   289	
   290	    // Check transcript if present
   291	    if (analyzed.transcript) {
   292	      const transcriptMatches = findAllergyMatches(analyzed.transcript, allergies);
   293	      if (transcriptMatches.length > 0) {
   294	        return {
   295	          status: 'unsafe',
   296	          notes: `Allergen mention (${transcriptMatches.join(', ')}) found in video transcript/summary. Treated as unsafe.`,
   297	        };
   298	      }
   299	    }
   300	
   301	    const severeAllergies = allergies.filter((a) =>
   302	      /peanut|tree.?nut|almond|walnut|cashew|shellfish|shrimp|fish|sesame|milk|egg|soy/i.test(
   303	        a,
   304	      ),
   305	    );
   306	
   307	    // 5: Partial coverage with severe allergies
   308	    if (analyzed.coverage === 'partial' && severeAllergies.length > 0) {
   309	      return {
   310	        status: 'uncertain',
   311	        notes: `Video coverage was only partial and user declared severe allergies (${severeAllergies.join(', ')}). Excluded as uncertain.`,
   312	      };
   313	    }
   314	
   315	    // 6: Offline mock analysis cannot confirm absence of severe allergens
   316	    if (
   317	      analyzed.provider === 'mock' &&
   318	      severeAllergies.length > 0 &&
   319	      analyzed.transcript &&
   320	      /no common allergens detected/i.test(analyzed.transcript)
   321	    ) {
   322	      return {
   323	        status: 'uncertain',
   324	        notes: `Offline mock analysis cannot confirm absence of ${severeAllergies.join(', ')} (cross-contact unknown). Review the full video/recipe before cooking.`,
   325	      };
   326	    }
   327	
   328	    return {
   329	      status: 'safe',
   330	      notes: `No match for declared allergies (${allergies.join(', ')}) in analyzed data. Still verify the full recipe — analysis may be incomplete.`,
   331	    };
   332	  }
   333	
   334	  private matchTags(
   335	    analyzed: { restrictionTags: string[]; nutritionSignals: string[] },
   336	    restrictions: string[],
   337	    healthText: string,
   338	  ): string[] {
   339	    const tags = new Set<string>();
   340	    const known = new Set(
   341	      [...analyzed.restrictionTags, ...analyzed.nutritionSignals].map(
   342	        normalizeRestriction,
   343	      ),
   344	    );
   345	
   346	    for (const r of restrictions) {
   347	      if (known.has(r)) {
   348	        tags.add(r);
   349	        continue;
   350	      }
   351	      if (r === 'vegetarian' && known.has('vegan')) tags.add('vegan');
   352	      if (r === 'gluten-free' && known.has('gluten-free')) tags.add('gluten-free');
   353	    }
   354	
   355	    for (const t of KNOWN_RESTRICTION_TAGS) {
   356	      if (known.has(t)) tags.add(t);
   357	    }
   358	
   359	    if (
   360	      /hypertension|high blood pressure|low sodium|140\/|150\//.test(healthText)
   361	    ) {
   362	      if (known.has('low-sodium')) tags.add('low-sodium');
   363	    }
   364	    if (/diabet/.test(healthText) && known.has('low-carb')) {
   365	      tags.add('low-carb');
   366	    }
   367	
   368	    return [...tags];
   369	  }
   370	
   371	  private explainFit(
   372	    analyzed: { title: string; summary: string },
   373	    restrictions: string[],
   374	    dto: MealPlanRequestDto,
   375	    matchedTags: string[],
   376	  ): string {
   377	    const bits: string[] = [];
   378	    bits.push(`"${analyzed.title}" fits because ${analyzed.summary}`);
   379	    if (restrictions.length) {
   380	      bits.push(
   381	        `Requested restrictions (${restrictions.join(', ')}) overlap with tags: ${matchedTags.join(', ') || 'none explicitly tagged — review recipe'}.`,
   382	      );
   383	    }
   384	    if (dto.bloodPressure) {
   385	      bits.push(
   386	        `Blood pressure noted as ${dto.bloodPressure}; prefer low-sodium preparations and confirm with a professional.`,
   387	      );
   388	    }
   389	    if (dto.healthProfile) {
   390	      bits.push(`Health context: ${dto.healthProfile}.`);
   391	    }
   392	    return bits.join(' ');
   393	  }
   394	
   395	  private healthNotes(
   396	    analyzed: { nutritionSignals: string[] },
   397	    dto: MealPlanRequestDto,
   398	  ): string {
   399	    const signals =
   400	      analyzed.nutritionSignals.join(', ') || 'no nutrition signals extracted';
   401	    return `Estimated signals (model, not measured): ${signals}. Profile: ${dto.healthProfile ?? 'not provided'}; BP: ${dto.bloodPressure ?? 'not provided'}. Informational only — not medical advice.`;
   402	  }
   403	}
