235	    10	export const RANKING_WEIGHTS = {
236	    11	  restrictionMatched: 2,
237	    12	  restrictionMissing: -3,
238	    13	  goalMatched: 2,
239	    14	  goalMissing: -1,
240	    15	  fullCoverage: 2,
241	    16	  trustedChannel: 1.5,
242	    17	  /** Multiplied by the share (0..1) of high-confidence ingredients. */
243	    18	  highConfidenceShare: 2,
244	    19	  fitsTime: 1,
245	    20	  /** Per already-selected recipe with the same main protein. */
246	    21	  repeatedProtein: -2,
247	    22	} as const;
