258	    33	  | 'videoId'
259	    34	  | 'channelId'
260	    35	  | 'restrictionTags'
261	    36	  | 'nutritionSignals'
262	    37	  | 'coverage'
263	    38	  | 'ingredients'
264	    39	  | 'prepMinutes'
265	    40	  | 'mainProtein'
266	    41	>;
267	    42	
268	    43	export interface RecipeScore {
269	    44	  score: number;
270	    45	  breakdown: Partial<Record<keyof typeof RANKING_WEIGHTS, number>>;
271	    46	}
272	    47	
273	    48	const NO_PROTEIN_PENALTY = new Set(['none', 'other', undefined]);
274	    49	
275	    50	export function scoreRecipe(
276	    51	  analysis: RankedAnalysis,
277	    52	  ctx: RankingContext,
278	    53	  alreadySelected: Pick<VideoAnalysis, 'mainProtein'>[] = [],
279	    54	): RecipeScore {
280	    55	  const w = RANKING_WEIGHTS;
281	    56	  const breakdown: RecipeScore['breakdown'] = {};
282	    57	  const add = (key: keyof typeof RANKING_WEIGHTS, value: number) => {
283	    58	    if (value !== 0) breakdown[key] = (breakdown[key] ?? 0) + value;
284	    59	  };
285	    60	
286	    61	  const restrictions = restrictionCoverage(analysis, ctx.restrictions);
287	    62	  add('restrictionMatched', restrictions.matched.length * w.restrictionMatched);
288	    63	  add('restrictionMissing', restrictions.missing.length * w.restrictionMissing);
289	    64	
290	    65	  const goals = matchGoals(analysis, ctx.healthGoals);
291	    66	  add('goalMatched', goals.matched.length * w.goalMatched);
292	    67	  add('goalMissing', goals.missing.length * w.goalMissing);
293	    68	
294	    69	  if (analysis.coverage === 'full') add('fullCoverage', w.fullCoverage);
295	    70	  if (ctx.isTrusted(analysis.channelId)) add('trustedChannel', w.trustedChannel);
296	    71	
297	    72	  const ingredients = analysis.ingredients ?? [];
298	    73	  if (ingredients.length) {
299	    74	    const high = ingredients.filter((i) => i.confidence === 'high').length;
300	    75	    add('highConfidenceShare', Math.round((high / ingredients.length) * w.highConfidenceShare * 100) / 100);
301	    76	  }
302	    77	
303	    78	  if (checkTime(analysis, ctx.maxCookMinutes).fitsTime === true) add('fitsTime', w.fitsTime);
304	    79	
305	    80	  if (!NO_PROTEIN_PENALTY.has(analysis.mainProtein)) {
306	    81	    const repeats = alreadySelected.filter((s) => s.mainProtein === analysis.mainProtein).length;
307	    82	    add('repeatedProtein', repeats * w.repeatedProtein);
308	    83	  }
309	    84	
310	    85	  const score = Object.values(breakdown).reduce((sum, v) => sum + (v ?? 0), 0);
