314	    89	/**
315	    90	 * Greedy selection: pick the best-scoring recipe, then re-score the rest
316	    91	 * with the protein penalty for what is already picked. Callers pass only
317	    92	 * candidates that already passed the safety and time gates.
318	    93	 */
319	    94	export function selectRanked<T extends RankedAnalysis>(
320	    95	  candidates: T[],
321	    96	  ctx: RankingContext,
322	    97	  max: number,
323	    98	): Array<{ analysis: T; score: RecipeScore }> {
324	    99	  const remaining = [...candidates];
325	   100	  const picked: Array<{ analysis: T; score: RecipeScore }> = [];
326	   101	  while (picked.length < max && remaining.length) {
327	   102	    let bestIdx = 0;
328	   103	    let best = scoreRecipe(remaining[0], ctx, picked.map((p) => p.analysis));
329	   104	    for (let i = 1; i < remaining.length; i++) {
330	   105	      const s = scoreRecipe(remaining[i], ctx, picked.map((p) => p.analysis));
331	   106	      if (s.score > best.score) {
332	   107	        best = s;
333	   108	        bestIdx = i;
334	   109	      }
335	   110	    }
336	   111	    picked.push({ analysis: remaining[bestIdx], score: best });
337	   112	    remaining.splice(bestIdx, 1);
338	   113	  }
339	   114	  return picked;
340	   115	}
