import {
  index,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  text,
  timestamp,
} from 'drizzle-orm/pg-core';

/**
 * Shared across users and deploys ("popular recipes are reused"). The
 * primary key's leading column also serves lookups by video_id.
 */
export const videoAnalyses = pgTable(
  'video_analyses',
  {
    videoId: text('video_id').notNull(),
    provider: text('provider').notNull(),
    model: text('model').notNull(),
    schemaVersion: integer('schema_version').notNull(),
    data: jsonb('data').notNull(),
    analyzedAt: timestamp('analyzed_at', { withTimezone: true }).notNull(),
  },
  (t) => [
    primaryKey({ columns: [t.videoId, t.provider, t.model, t.schemaVersion] }),
    index('video_analyses_analyzed_at_idx').on(t.analyzedAt),
  ],
);

/** Ingredient name to FDC food, reused across all videos. fdc_id null = no match. */
export const fdcMappings = pgTable('fdc_mappings', {
  normalisedName: text('normalised_name').primaryKey(),
  fdcId: integer('fdc_id'),
  description: text('description'),
  dataType: text('data_type'),
  nutrients: jsonb('nutrients'),
  portions: jsonb('portions'),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull(),
});

export const youtubeSearchCache = pgTable('youtube_search_cache', {
  queryNorm: text('query_norm').primaryKey(),
  videoIds: jsonb('video_ids').$type<string[]>().notNull(),
  cachedAt: timestamp('cached_at', { withTimezone: true }).notNull(),
});

import * as path from 'path';
import { Client } from 'pg';
import { drizzle } from 'drizzle-orm/node-postgres';
import { migrate } from 'drizzle-orm/node-postgres/migrator';

export const MIGRATIONS_FOLDER = path.join(process.cwd(), 'drizzle');

/** Arbitrary constant shared by every instance, so only one migrates at a time. */
const MIGRATION_LOCK_KEY = 4_216_801;

/**
 * Applies pending SQL migrations from drizzle/ over the direct (unpooled)
 * URL. Session advisory locks don't survive PgBouncer transaction pooling,
 * which is why this must never use the pooled DATABASE_URL.
 */
export async function runMigrations(directUrl: string): Promise<void> {
  const client = new Client({ connectionString: directUrl, connectionTimeoutMillis: 10_000 });
  await client.connect();
  try {
    await client.query('SELECT pg_advisory_lock($1)', [MIGRATION_LOCK_KEY]);
    try {
      await migrate(drizzle(client), { migrationsFolder: MIGRATIONS_FOLDER });
    } finally {
      await client.query('SELECT pg_advisory_unlock($1)', [MIGRATION_LOCK_KEY]);
    }
  } finally {
    await client.end();
  }
}

import {
  Injectable,
  Logger,
  OnModuleDestroy,
  OnModuleInit,
} from '@nestjs/common';
import { drizzle, NodePgDatabase } from 'drizzle-orm/node-postgres';
import { Pool } from 'pg';
import { AppConfigService } from '../config/app-config.service';
import { runMigrations } from './migrate';
import * as schema from './schema';

export type Db = NodePgDatabase<typeof schema>;
export type DbStatus = 'up' | 'down' | 'disabled';

const SLOW_QUERY_MS = 500;

/** Errors worth one retry: Neon waking from scale-to-zero, dropped sockets. */
export function isConnectionError(err: unknown): boolean {
  const e = err as { code?: string; message?: string };
  if (e?.code && /^(ECONNREFUSED|ECONNRESET|ETIMEDOUT|EPIPE|57P01|57P03|08\w{3})$/.test(e.code)) {
    return true;
  }
  return /connection terminated|timeout exceeded when trying to connect/i.test(e?.message ?? '');
}

/**
 * One pg pool against the pooled DATABASE_URL, or nothing when it is empty
 * (file stores are used then). PgBouncer runs in transaction mode, so code
 * here must avoid session SET, LISTEN/NOTIFY and session advisory locks.
 */
@Injectable()
export class DatabaseService implements OnModuleInit, OnModuleDestroy {
  private readonly logger = new Logger(DatabaseService.name);
  private readonly pool: Pool | null;
  private readonly database: Db | null;

  constructor(private readonly config: AppConfigService) {
    const url = config.databaseUrl;
    if (!url) {
      this.pool = null;
      this.database = null;
      return;
    }
    this.pool = new Pool({
      connectionString: url,
      max: 5,
      idleTimeoutMillis: 30_000,
      connectionTimeoutMillis: 10_000,
    });
    // Never log the error object itself: it can carry connection details.
    this.pool.on('error', (err) => this.logger.error(`Postgres pool error: ${err.message}`));
    this.database = drizzle(this.pool, { schema });
  }

  get enabled(): boolean {
    return this.database !== null;
  }

  async onModuleInit(): Promise<void> {
    if (this.enabled && this.config.databaseUrlDirect) {
      await runMigrations(this.config.databaseUrlDirect);
      this.logger.log('Database migrations applied');
    }
  }

  async onModuleDestroy(): Promise<void> {
    await this.pool?.end();
  }

  /** Runs a query, retrying once on connection errors, and logs slow ones. */
  async run<T>(label: string, fn: (db: Db) => Promise<T>): Promise<T> {
    if (!this.database) throw new Error('Database is not configured');
    const startedAt = Date.now();
    try {
      return await fn(this.database);
    } catch (err) {
      if (!isConnectionError(err)) throw err;
      this.logger.warn(`${label}: connection error, retrying once`);
      return await fn(this.database);
    } finally {
      const ms = Date.now() - startedAt;
      if (ms > SLOW_QUERY_MS) this.logger.warn(`${label} took ${ms} ms`);
      else this.logger.debug(`${label} took ${ms} ms`);
    }
  }

  /** SELECT 1 with a short timeout, so a cold start reports down, not a hang. */
  async ping(timeoutMs = 2_000): Promise<DbStatus> {
    if (!this.pool) return 'disabled';
    let timer: NodeJS.Timeout | undefined;
    try {
      await Promise.race([
        this.pool.query('SELECT 1'),
        new Promise((_, reject) => {
          timer = setTimeout(() => reject(new Error('timeout')), timeoutMs);
        }),
      ]);
      return 'up';
    } catch {
      return 'down';
    } finally {
      clearTimeout(timer);
    }
  }
}

