  ) {}

  /**
   * Always 200, so Render's health check never fails on a slow first query
   * after Neon scales to zero; a down database reports `degraded` instead.
   */
  @Get()
  @ApiOkResponse({
    schema: {
      example: {
        status: 'ok',
        service: 'meal-pilot',
        mode: 'mock',
        model: 'gemini-3.8-flash',
        db: 'disabled',
