/**
 * Parsing for USDA FoodData Central responses. Search hits, full and
 * abridged food details each spell nutrients differently; this reads all
 * three. Foundation and SR Legacy values are per 100 g of edible food.
 */

export const NUTRIENT_KEYS = [
  'kcal',
  'protein',
  'fat',
  'saturatedFat',
  'carbs',
  'sugar',
  'fiber',
  'sodium',
] as const;
export type NutrientKey = (typeof NUTRIENT_KEYS)[number];
export type Nutrients = Partial<Record<NutrientKey, number>>;

/**
 * FDC nutrient numbers, in order of preference. Foundation foods often
 * report energy only as Atwater factors (957, 958) instead of 208, and total
 * sugars as 269.3 instead of 269. Sodium is in mg, everything else g or kcal.
 */
const NUTRIENT_NUMBERS: Record<NutrientKey, string[]> = {
  kcal: ['208', '957', '958'],
  protein: ['203'],
  fat: ['204'],
  saturatedFat: ['606'],
  carbs: ['205'],
  sugar: ['269', '269.3'],
  fiber: ['291'],
  sodium: ['307'],
};

export interface Portion {
  /** e.g. "1 cup, chopped", "1 clove", "1 medium (2-3/4\" dia)" */
  label: string;
  amount: number;
  gramWeight: number;
}

export interface FdcFood {
  fdcId: number;
  description: string;
  dataType: string;
  /** Per 100 g. */
  nutrients: Nutrients;
  portions: Portion[];
}

type RawNutrient = {
  nutrientNumber?: string;
  number?: string;
  unitName?: string;
  value?: number;
  amount?: number;
  nutrient?: { number?: string; unitName?: string };
};

type RawPortion = {
  amount?: number;
  gramWeight?: number;
  modifier?: string;
  portionDescription?: string;
  measureUnit?: { name?: string; abbreviation?: string };
};

export type RawFood = {
  fdcId: number;
  description: string;
  dataType: string;
  foodNutrients?: RawNutrient[];
  foodPortions?: RawPortion[];
};

export function parseNutrients(raw: RawNutrient[] | undefined): Nutrients {
  const byNumber = new Map<string, number>();
  for (const n of raw ?? []) {
    const number = n.nutrientNumber ?? n.number ?? n.nutrient?.number;
    const unit = (n.unitName ?? n.nutrient?.unitName ?? '').toLowerCase();
    const value = n.value ?? n.amount;
    if (!number || typeof value !== 'number') continue;
    // Energy is also reported in kJ under other numbers; never mix units.
    if (['208', '957', '958'].includes(number) && unit !== 'kcal') continue;
    if (!byNumber.has(number)) byNumber.set(number, value);
  }
  const out: Nutrients = {};
  for (const key of NUTRIENT_KEYS) {
    const number = NUTRIENT_NUMBERS[key].find((n) => byNumber.has(n));
    if (number) out[key] = byNumber.get(number)!;
  }
  return out;
}

export function parsePortions(raw: RawPortion[] | undefined): Portion[] {
  const out: Portion[] = [];
  for (const p of raw ?? []) {
    if (!p.gramWeight || p.gramWeight <= 0) continue;
    const unit = p.measureUnit?.name && p.measureUnit.name !== 'undetermined' ? p.measureUnit.name : '';
    const text = [unit, p.modifier, p.portionDescription].filter(Boolean).join(', ');
    out.push({
      label: `${p.amount ?? 1} ${text}`.trim().toLowerCase(),
      amount: p.amount && p.amount > 0 ? p.amount : 1,
      gramWeight: p.gramWeight,
    });
  }
  return out;
}

export function parseFood(raw: RawFood): FdcFood {
  return {
    fdcId: raw.fdcId,
    description: raw.description,
    dataType: raw.dataType,
    nutrients: parseNutrients(raw.foodNutrients),
    portions: parsePortions(raw.foodPortions),
  };
}

import { Injectable } from '@nestjs/common';
import { AppConfigService } from '../config/app-config.service';
import { FdcFood, parseFood, RawFood } from './fdc-food';

export const FDC_CLIENT = Symbol('FDC_CLIENT');

const BASE_URL = 'https://api.nal.usda.gov/fdc/v1';
/** Generic foods with full nutrient profiles; branded foods are excluded. */
export const FDC_DATA_TYPES = ['Foundation', 'SR Legacy'];
const SEARCH_PAGE_SIZE = 25;
const MAX_IDS_PER_REQUEST = 20;
const TIMEOUT_MS = 10_000;

export interface FdcClient {
  readonly enabled: boolean;
  /** Ranked hits; portions are empty here (search doesn't return them). */
  search(query: string): Promise<FdcFood[]>;
  /** Full details with portions, batched. */
  foods(fdcIds: number[]): Promise<FdcFood[]>;
}

/**
 * FDC allows 1,000 requests per hour per key. The mapping cache keeps real
 * use far below that: each ingredient name costs one search, once.
 */
@Injectable()
export class HttpFdcClient implements FdcClient {
  constructor(private readonly config: AppConfigService) {}

  get enabled(): boolean {
    return Boolean(this.config.fdcApiKey);
  }

  async search(query: string): Promise<FdcFood[]> {
    const params = new URLSearchParams({
      query,
      dataType: FDC_DATA_TYPES.join(','),
      pageSize: String(SEARCH_PAGE_SIZE),
    });
    const body = (await this.request(`/foods/search?${params}`)) as { foods?: RawFood[] };
    return (body.foods ?? []).map(parseFood);
  }

  async foods(fdcIds: number[]): Promise<FdcFood[]> {
    const out: FdcFood[] = [];
    for (let i = 0; i < fdcIds.length; i += MAX_IDS_PER_REQUEST) {
      const chunk = fdcIds.slice(i, i + MAX_IDS_PER_REQUEST);
      const body = (await this.request('/foods', {
        method: 'POST',
        body: JSON.stringify({ fdcIds: chunk, format: 'full' }),
      })) as RawFood[];
      out.push(...body.map(parseFood));
    }
    return out;
  }

  /** The key goes in a header, never the URL, so it can't leak into logs. */
  private async request(path: string, init: RequestInit = {}): Promise<unknown> {
    const res = await fetch(`${BASE_URL}${path}`, {
      ...init,
      headers: { 'X-Api-Key': this.config.fdcApiKey, 'Content-Type': 'application/json' },
      signal: AbortSignal.timeout(TIMEOUT_MS),
    });
    if (!res.ok) throw new Error(`FDC request failed (${res.status})`);
    return res.json();
  }
}

import { singularize } from '../recipes/normalize';
import { FdcFood } from './fdc-food';

export interface MatchHints {
  /** The recipe uses a can or tin ("1 can chickpeas"). */
  canned: boolean;
}

/** Product forms that change the nutrients; they only match when the ingredient names them. */
const FORM_WORDS = [
  'flour',
  'powder',
  'dehydrated',
  'flakes',
  'dried',
  'mix',
  'pudding',
  'babyfood',
  'toddler',
  'infant',
  'juice',
  'beverage',
  'sweetened',
  'frozen',
  'bread',
  'breadstick',
  'ring',
  'soup',
  'sauce',
  'mayonnaise',
  'prepared',
  'sprouted',
  'candy',
  'snack',
  'cereal',
  'imitation',
  'restaurant',
  'fast',
];

const MIN_SCORE = 2;

function words(text: string): string[] {
  return text
    .toLowerCase()
    .replace(/[^a-z\s]/g, ' ')
    .split(/\s+/)
    .filter(Boolean)
    .map(singularize);
}

/** Brand or restaurant items are written in capitals in FDC ("DENNY'S, onion rings"). */
const BRAND = /\b[A-Z][A-Z'&]{2,}\b/;

export interface ScoredFood {
  food: FdcFood;
  score: number;
}

/**
 * Scores one FDC hit for an ingredient. Every ingredient word must appear;
 * words in the first two description segments ("Oil, olive, ...") count
 * extra, product forms the ingredient doesn't name are penalised, and raw
 * foods are preferred unless the recipe uses a can.
 */
export function scoreFood(name: string, hints: MatchHints, food: FdcFood): number {
  if (food.nutrients.kcal === undefined || food.nutrients.protein === undefined) return -Infinity;

  const nameWords = new Set(words(name));
  const segments = food.description.split(',').map(words);
  const descWords = new Set(segments.flat());
  const leading = new Set([...(segments[0] ?? []), ...(segments[1] ?? [])]);

  if (![...nameWords].every((w) => descWords.has(w))) return -Infinity;

  let score = 3;
  if ([...nameWords].every((w) => leading.has(w))) score += 2;
  for (const form of FORM_WORDS) {
    if (descWords.has(form) && !nameWords.has(form)) score -= 3;
  }
  if (BRAND.test(food.description)) score -= 4;

  const canned = descWords.has('canned');
  if (hints.canned) {
    score += canned ? 3 : -1;
    if (descWords.has('drained')) score += 1;
  } else {
    if (descWords.has('raw')) score += 1;
    if (canned) score -= 1;
  }

  if (Object.keys(food.nutrients).length === 8) score += 1;
  return score;
}

/** Best hit, or null when nothing is a confident match. Ties keep FDC's relevance order. */
export function pickFood(name: string, hints: MatchHints, hits: FdcFood[]): FdcFood | null {
  let best: ScoredFood | null = null;
  for (const food of hits) {
    const score = scoreFood(name, hints, food);
    if (score >= MIN_SCORE && (!best || score > best.score)) best = { food, score };
  }
  return best?.food ?? null;
}

