import { densityFor, toBaseUnit } from '../recipes/units';
import { Ingredient } from '../videos/analyzers/analysis.schema';
import { Portion } from './fdc-food';

export type GramsMethod = 'mass' | 'density' | 'portion' | 'label';

export type GramsResult =
  | { grams: number; method: GramsMethod }
  | { grams: null; reason: string };

const ML_PER: Record<string, number> = { cup: 240, tbsp: 15, tablespoon: 15, tsp: 5, teaspoon: 5, 'fl oz': 29.57, ml: 1 };

/** FDC portion words that stand for one counted item, best first. */
const COUNT_PORTIONS: Record<string, RegExp[]> = {
  piece: [/\bmedium\b/, /\b(whole|piece|unit|fruit|each|item|egg)\b/, /\blarge\b/, /\bsmall\b/],
  clove: [/\bclove\b/],
  slice: [/\bslice\b/],
  can: [/\bcan\b/],
  bunch: [/\bbunch\b/],
};

function gramsPerMl(portions: Portion[]): number | null {
  for (const p of portions) {
    for (const [unit, ml] of Object.entries(ML_PER)) {
      if (new RegExp(`^[\\d.]+ ${unit}\\b`).test(p.label)) return p.gramWeight / (p.amount * ml);
    }
  }
  return null;
}

function gramsPerCount(unit: string, portions: Portion[]): number | null {
  for (const pattern of COUNT_PORTIONS[unit] ?? []) {
    const p = portions.find((x) => pattern.test(x.label));
    if (p) return p.gramWeight / p.amount;
  }
  return null;
}

/** "1 can (400g) chickpeas": an explicit weight per item in the text as said or written. */
function labelWeight(rawText: string): number | null {
  const m = rawText.match(/(\d+(?:\.\d+)?)\s*(g|ml)\b/i);
  return m ? Number(m[1]) : null;
}

/**
 * Grams of one ingredient for nutrient maths. Mass units convert directly,
 * volume through the density table or an FDC cup/tbsp portion, counts
 * through FDC portions ("1 clove", "1 medium"). Anything else, and every
 * low-confidence amount, stays unresolved rather than guessed.
 */
export function resolveGrams(i: Ingredient, portions: Portion[]): GramsResult {
  if (i.confidence === 'low') return { grams: null, reason: 'low confidence' };
  if (i.quantity === null || i.quantity <= 0 || i.unit === null) return { grams: null, reason: 'no amount' };

  const base = toBaseUnit(i.quantity, i.unit);
  if (!base) return { grams: null, reason: `unit ${i.unit}` };
  if (base.unit === 'g') return { grams: base.amount, method: 'mass' };

  if (base.unit === 'ml') {
    const density = densityFor(i.name);
    if (density !== null) return { grams: base.amount * density, method: 'density' };
    const perMl = gramsPerMl(portions);
    if (perMl !== null) return { grams: base.amount * perMl, method: 'portion' };
    return { grams: null, reason: 'no density for volume' };
  }

  const perItem = gramsPerCount(base.unit, portions);
  if (perItem !== null) return { grams: base.amount * perItem, method: 'portion' };
  const label = base.amount === 1 ? labelWeight(i.rawText) : null;
  if (label !== null) return { grams: label, method: 'label' };
  return { grams: null, reason: `no portion for ${base.unit}` };
}

import { normalizeIngredientName } from '../recipes/normalize';
import { approximateGrams } from '../recipes/units';
import { Ingredient, VideoAnalysis } from '../videos/analyzers/analysis.schema';
import { FdcFood, NUTRIENT_KEYS, NutrientKey, Nutrients } from './fdc-food';
import { MatchHints } from './food-match';
import { resolveGrams } from './grams';

/** Bump when mapping or maths change; stored nutrients with another version are recomputed. */
export const NUTRITION_VERSION = 1;

/** Below this share of resolved recipe mass the numbers are a partial estimate. */
export const MIN_COMPLETENESS = 0.7;

/** Denominator mass for an ingredient whose amount is unknown ("salt to taste"). */
const NOMINAL_UNKNOWN_GRAMS = 20;

export type NutrientTotals = Record<NutrientKey, number>;

export interface NutritionResult {
  /** Null when servings are unknown: a whole-recipe figure would mislead. */
  perServing: NutrientTotals | null;
  total: NutrientTotals;
  servings: number | null;
  /** Share (0..1) of total recipe mass that was resolved to an FDC food and grams. */
  completeness: number;
  /** Per nutrient: share of recipe mass whose food reports that nutrient. */
  nutrientCompleteness: Record<NutrientKey, number>;
  /** completeness below MIN_COMPLETENESS: show as "partial estimate". */
  partial: boolean;
  unresolved: string[];
  estimated: true;
  source: 'USDA FoodData Central';
  version: number;
}

/** "1 can chickpeas" and "chickpea" map to different FDC foods (canned vs dry). */
export function matchHints(i: Ingredient): MatchHints {
  return { canned: i.unit === 'can' || /\b(canned|tinned|tin|can)\b/i.test(i.rawText) };
}

export function mappingKey(i: Ingredient): string {
  const name = normalizeIngredientName(i.name);
  return matchHints(i).canned ? `${name}|canned` : name;
}

function round(key: NutrientKey, value: number): number {
  return key === 'kcal' || key === 'sodium' ? Math.round(value) : Math.round(value * 10) / 10;
}

function zeros(): NutrientTotals {
  return Object.fromEntries(NUTRIENT_KEYS.map((k) => [k, 0])) as NutrientTotals;
}

/**
 * Sums ingredient nutrients from their FDC foods and divides by servings.
 * `foods` maps mappingKey to the matched food, or null for no match.
 */
export function computeNutrition(
  analysis: Pick<VideoAnalysis, 'ingredients' | 'servings'>,
  foods: Map<string, FdcFood | null>,
): NutritionResult {
  const total = zeros();
  const nutrientMass = zeros();
  let totalMass = 0;
  let resolvedMass = 0;
  const unresolved: string[] = [];

  for (const i of analysis.ingredients ?? []) {
    const food = foods.get(mappingKey(i)) ?? null;
    const grams = resolveGrams(i, food?.portions ?? []);
    const mass =
      grams.grams ?? (approximateGrams(i.quantity, i.unit, i.name) || NOMINAL_UNKNOWN_GRAMS);
    totalMass += mass;

    if (!food || grams.grams === null) {
      unresolved.push(i.name);
      continue;
    }
    resolvedMass += grams.grams;
    for (const key of NUTRIENT_KEYS) {
      const per100 = (food.nutrients as Nutrients)[key];
      if (per100 === undefined) continue;
      total[key] += (per100 * grams.grams) / 100;
      nutrientMass[key] += grams.grams;
    }
  }

  const share = (m: number) => (totalMass > 0 ? Math.round((m / totalMass) * 100) / 100 : 0);
  const servings = analysis.servings && analysis.servings > 0 ? analysis.servings : null;
  const completeness = share(resolvedMass);

  return {
    perServing: servings
      ? (Object.fromEntries(NUTRIENT_KEYS.map((k) => [k, round(k, total[k] / servings)])) as NutrientTotals)
      : null,
    total: Object.fromEntries(NUTRIENT_KEYS.map((k) => [k, round(k, total[k])])) as NutrientTotals,
    servings,
    completeness,
    nutrientCompleteness: Object.fromEntries(NUTRIENT_KEYS.map((k) => [k, share(nutrientMass[k])])) as Record<
      NutrientKey,
      number
    >,
    partial: completeness < MIN_COMPLETENESS,
    unresolved: [...new Set(unresolved)],
    estimated: true,
    source: 'USDA FoodData Central',
    version: NUTRITION_VERSION,
  };
}

import { VideoAnalysis } from '../videos/analyzers/analysis.schema';
import { NutrientKey } from './fdc-food';
import { MIN_COMPLETENESS, NutrientTotals } from './nutrition';

/**
 * Fixed per-serving thresholds (one serving is one meal). They replace the
 * model's labels once nutrients are computed.
 * - high-protein: at least 20 g protein
 * - low-sodium: at most 600 mg sodium; moderate-sodium: at most 1,000 mg
 * - high-fiber: at least 8 g fibre
 * - low-carb: at most 30 g carbohydrate
 * - low-sugar: at most 10 g total sugars
 * Not medical targets: they only sort recipes, and the app shows them as estimates.
 */
export const SIGNAL_THRESHOLDS = {
  highProteinG: 20,
  lowSodiumMg: 600,
  moderateSodiumMg: 1000,
  highFiberG: 8,
  lowCarbG: 30,
  lowSugarG: 10,
  quickPrepMinutes: 30,
} as const;

/** Labels that describe nutrients; the model also puts some in restrictionTags. */
export const NUTRIENT_TAGS = new Set(['low-sodium', 'moderate-sodium', 'high-protein', 'high-fiber', 'low-carb', 'low-sugar']);

/** Which nutrient each nutrient label rests on. */
export const SIGNAL_NUTRIENT: Record<string, NutrientKey> = {
  'high-protein': 'protein',
  'low-sodium': 'sodium',
  'moderate-sodium': 'sodium',
  'high-fiber': 'fiber',
  'low-carb': 'carbs',
  'low-sugar': 'sugar',
};

/**
 * - nutrients: computed from USDA FoodData Central (completeness >= 0.7)
 * - model: Gemini's estimates, from analyses made before nutrients existed
 * - none: no nutrient basis; only prep time and whole-foods are known
 */
export type NutritionBasis = 'nutrients' | 'model' | 'none';

export type FactsInput = Pick<
  VideoAnalysis,
  'nutrition' | 'nutritionSignals' | 'restrictionTags' | 'prepMinutes' | 'ingredients'
>;

export interface NutritionFacts {
  basis: NutritionBasis;
  signals: string[];
  /** Restriction tags with model nutrient labels replaced when nutrients are computed. */
  tags: string[];
  perServing: NutrientTotals | null;
  /** True when the nutrient behind a label was reported for enough of the recipe. */
  covers(signal: string): boolean;
}

function nutrientSignals(perServing: NutrientTotals, covered: (k: NutrientKey) => boolean): string[] {
  const t = SIGNAL_THRESHOLDS;
  const out: string[] = [];
  if (covered('protein') && perServing.protein >= t.highProteinG) out.push('high-protein');
  if (covered('sodium')) {
    if (perServing.sodium <= t.lowSodiumMg) out.push('low-sodium');
    else if (perServing.sodium <= t.moderateSodiumMg) out.push('moderate-sodium');
  }
  if (covered('fiber') && perServing.fiber >= t.highFiberG) out.push('high-fiber');
  if (covered('carbs') && perServing.carbs <= t.lowCarbG) out.push('low-carb');
  if (covered('sugar') && perServing.sugar <= t.lowSugarG) out.push('low-sugar');
  return out;
}

function recipeSignals(a: FactsInput): string[] {
  const out: string[] = [];
  if (typeof a.prepMinutes === 'number' && a.prepMinutes <= SIGNAL_THRESHOLDS.quickPrepMinutes) out.push('quick-prep');
  if ((a.ingredients ?? []).length && !(a.ingredients ?? []).some((i) => i.packaged)) out.push('whole-foods');
  return out;
}

export function nutritionFacts(a: FactsInput): NutritionFacts {
  const n = a.nutrition;
  const modelTags = a.restrictionTags ?? [];

  if (n && !n.partial && n.perServing) {
    const covered = (k: NutrientKey) => (n.nutrientCompleteness?.[k] ?? 0) >= MIN_COMPLETENESS;
    const signals = [...nutrientSignals(n.perServing, covered), ...recipeSignals(a)];
    const tags = [...modelTags.filter((t) => !NUTRIENT_TAGS.has(t)), ...signals.filter((s) => NUTRIENT_TAGS.has(s))];
    return {
      basis: 'nutrients',
      signals,
      tags: [...new Set(tags)],
      perServing: n.perServing,
      covers: (s) => !SIGNAL_NUTRIENT[s] || covered(SIGNAL_NUTRIENT[s]),
    };
  }

  const model = a.nutritionSignals ?? [];
  return {
    basis: model.length ? 'model' : 'none',
    signals: model.length ? [...model] : recipeSignals(a),
    tags: [...modelTags],
    perServing: null,
    // Gemini never estimated sugar, so it can't speak to low-sugar.
    covers: (s) => model.length > 0 && s !== 'low-sugar',
  };
}

