import { Injectable, Logger } from '@nestjs/common';
import { eq } from 'drizzle-orm';
import * as fs from 'fs';
import * as path from 'path';
import { DatabaseService } from '../db/database.service';
import { fdcMappings } from '../db/schema';
import { FdcFood, Nutrients, Portion } from './fdc-food';

export const FDC_MAPPING_STORE = Symbol('FDC_MAPPING_STORE');

/** A "no match" is retried after this long, in case FDC or the matcher improved. */
export const NO_MATCH_TTL_MS = 30 * 24 * 60 * 60 * 1000;

export interface FdcMapping {
  /** mappingKey(): normalised name, plus "|canned" for canned products. */
  key: string;
  food: FdcFood | null;
  updatedAt: string;
}

/** Ingredient-to-food mappings are kept permanently and shared by every video. */
export interface FdcMappingStore {
  get(key: string): Promise<FdcMapping | null>;
  set(mapping: FdcMapping): Promise<void>;
}

export function isUsable(mapping: FdcMapping | null): mapping is FdcMapping {
  if (!mapping) return false;
  return mapping.food !== null || Date.now() - new Date(mapping.updatedAt).getTime() < NO_MATCH_TTL_MS;
}

/** One JSON file next to the analysis cache, for runs without a database. */
export class FileFdcMappingStore implements FdcMappingStore {
  private readonly logger = new Logger(FileFdcMappingStore.name);
  private entries: Record<string, FdcMapping> | null = null;

  private file(): string {
    const dir = process.env.MEALPILOT_CACHE_DIR || path.join(process.cwd(), 'data', 'cache');
    fs.mkdirSync(dir, { recursive: true });
    return path.join(dir, 'fdc-mappings.json');
  }

  private load(): Record<string, FdcMapping> {
    if (!this.entries) {
      try {
        this.entries = JSON.parse(fs.readFileSync(this.file(), 'utf8'));
      } catch {
        this.entries = {};
      }
    }
    return this.entries!;
  }

  async get(key: string): Promise<FdcMapping | null> {
    return this.load()[key] ?? null;
  }

  async set(mapping: FdcMapping): Promise<void> {
    const entries = this.load();
    entries[mapping.key] = mapping;
    try {
      fs.writeFileSync(this.file(), JSON.stringify(entries, null, 2));
    } catch (err) {
      this.logger.warn(`Could not persist FDC mappings: ${(err as Error).message}`);
    }
  }
}

@Injectable()
export class PgFdcMappingStore implements FdcMappingStore {
  constructor(private readonly database: DatabaseService) {}

  async get(key: string): Promise<FdcMapping | null> {
    const rows = await this.database.run('fdc.get', (db) =>
      db.select().from(fdcMappings).where(eq(fdcMappings.normalisedName, key)).limit(1),
    );
    const row = rows[0];
    if (!row) return null;
    return {
      key,
      food:
        row.fdcId === null
          ? null
          : {
              fdcId: row.fdcId,
              description: row.description ?? '',
              dataType: row.dataType ?? '',
              nutrients: (row.nutrients ?? {}) as Nutrients,
              portions: (row.portions ?? []) as Portion[],
            },
      updatedAt: row.updatedAt.toISOString(),
    };
  }

  async set(mapping: FdcMapping): Promise<void> {
    const values = {
      fdcId: mapping.food?.fdcId ?? null,
      description: mapping.food?.description ?? null,
      dataType: mapping.food?.dataType ?? null,
      nutrients: mapping.food?.nutrients ?? null,
      portions: mapping.food?.portions ?? null,
      updatedAt: new Date(mapping.updatedAt),
    };
    await this.database.run('fdc.set', (db) =>
      db
        .insert(fdcMappings)
        .values({ normalisedName: mapping.key, ...values })
        .onConflictDoUpdate({ target: fdcMappings.normalisedName, set: values }),
    );
  }
}

import { Inject, Injectable, Logger } from '@nestjs/common';
import * as fs from 'fs';
import * as path from 'path';
import { normalizeIngredientName } from '../recipes/normalize';
import { Ingredient, VideoAnalysis } from '../videos/analyzers/analysis.schema';
import { FdcFood } from './fdc-food';
import { FDC_MAPPING_STORE, FdcMappingStore, isUsable } from './fdc-mapping.store';
import { FDC_CLIENT, FdcClient } from './fdc.client';
import { pickFood } from './food-match';
import { computeNutrition, mappingKey, matchHints, NUTRITION_VERSION } from './nutrition';

export const FDC_OVERRIDES_FILE = path.join(process.cwd(), 'data', 'fdc-overrides.json');

/** Team-reviewed fixes for common mismatches, keyed like mappingKey(). */
export type FdcOverrides = Record<string, { fdcId: number; note?: string }>;

export function loadOverrides(file = FDC_OVERRIDES_FILE): FdcOverrides {
  try {
    const parsed = JSON.parse(fs.readFileSync(file, 'utf8')) as { overrides?: FdcOverrides };
    return parsed.overrides ?? {};
  } catch {
    return {};
  }
}

/** Ingredients worth a lookup: the rest stay unresolved whatever the food. */
function lookupWorthy(i: Ingredient): boolean {
  return i.confidence !== 'low' && i.quantity !== null && i.unit !== null && i.unit !== 'pinch';
}

/**
 * Adds USDA-based nutrients to an analysis. Gemini only extracts the
 * ingredients; matching, grams and sums happen here, in code. When FDC is
 * down the analysis still comes back, with `nutrition: null`.
 */
@Injectable()
export class NutritionService {
  private readonly logger = new Logger(NutritionService.name);
  private readonly inflight = new Map<string, Promise<FdcFood | null>>();
  private readonly overrides: FdcOverrides;

  constructor(
    @Inject(FDC_CLIENT) private readonly client: FdcClient,
    @Inject(FDC_MAPPING_STORE) private readonly mappings: FdcMappingStore,
    overrides?: FdcOverrides,
  ) {
    this.overrides = overrides ?? loadOverrides();
  }

  get enabled(): boolean {
    return this.client.enabled;
  }

  /** True when the analysis lacks current nutrients and could get them. */
  needsUpdate(analysis: VideoAnalysis): boolean {
    return this.enabled && analysis.status === 'ok' && analysis.nutrition?.version !== NUTRITION_VERSION;
  }

  async ensure(analysis: VideoAnalysis): Promise<VideoAnalysis> {
    if (!this.needsUpdate(analysis)) return analysis;
    try {
      const foods = new Map<string, FdcFood | null>();
      const wanted = new Map<string, Ingredient>();
      for (const i of analysis.ingredients ?? []) {
        if (lookupWorthy(i)) wanted.set(mappingKey(i), i);
      }
      await Promise.all(
        [...wanted].map(async ([key, i]) => foods.set(key, await this.foodFor(key, i))),
      );
      return { ...analysis, nutrition: computeNutrition(analysis, foods) };
    } catch (err) {
      this.logger.warn(`Nutrients unavailable for ${analysis.videoId}: ${(err as Error).message}`);
      return { ...analysis, nutrition: null };
    }
  }

  /** Concurrent analyses share one lookup per ingredient. */
  private foodFor(key: string, i: Ingredient): Promise<FdcFood | null> {
    let pending = this.inflight.get(key);
    if (!pending) {
      pending = this.lookup(key, i).finally(() => this.inflight.delete(key));
      this.inflight.set(key, pending);
    }
    return pending;
  }

  private async lookup(key: string, i: Ingredient): Promise<FdcFood | null> {
    const cached = await this.mappings.get(key);
    if (isUsable(cached)) return cached.food;

    const name = normalizeIngredientName(i.name);
    const hints = matchHints(i);
    const override = this.overrides[key] ?? this.overrides[name];

    let fdcId: number | null = override?.fdcId ?? null;
    if (fdcId === null) {
      const hits = await this.client.search(hints.canned ? `${name} canned` : name);
      fdcId = pickFood(name, hints, hits)?.fdcId ?? null;
    }
    // Details carry the portions ("1 clove") that search results lack.
    const food = fdcId === null ? null : ((await this.client.foods([fdcId]))[0] ?? null);
    await this.mappings.set({ key, food, updatedAt: new Date().toISOString() });
    return food;
  }
}

import { Module, Provider } from '@nestjs/common';
import { DatabaseService } from '../db/database.service';
import {
  FDC_MAPPING_STORE,
  FdcMappingStore,
  FileFdcMappingStore,
  PgFdcMappingStore,
} from './fdc-mapping.store';
import { FDC_CLIENT, HttpFdcClient } from './fdc.client';
import { NutritionService } from './nutrition.service';

const mappingStoreProvider: Provider = {
  provide: FDC_MAPPING_STORE,
  useFactory: (database: DatabaseService): FdcMappingStore =>
    database.enabled ? new PgFdcMappingStore(database) : new FileFdcMappingStore(),
  inject: [DatabaseService],
};

@Module({
  providers: [
    { provide: FDC_CLIENT, useClass: HttpFdcClient },
    mappingStoreProvider,
    {
      provide: NutritionService,
      useFactory: (client, store) => new NutritionService(client, store),
      inject: [FDC_CLIENT, FDC_MAPPING_STORE],
    },
  ],
  exports: [NutritionService],
})
export class NutritionModule {}

