import { ingredient } from '../../test/fixtures/analysis';
import { FdcFood } from './fdc-food';
import { computeNutrition, mappingKey } from './nutrition';

const food = (fdcId: number, nutrients: FdcFood['nutrients']): FdcFood => ({
  fdcId,
  description: `food ${fdcId}`,
  dataType: 'SR Legacy',
  nutrients,
  portions: [],
});

const lentil = food(1, { kcal: 352, protein: 24.6, fat: 1.1, saturatedFat: 0.2, carbs: 63.4, sugar: 2, fiber: 10.7, sodium: 6 });
const oil = food(2, { kcal: 884, protein: 0, fat: 100, saturatedFat: 13.8, carbs: 0, sugar: 0, fiber: 0, sodium: 2 });

describe('computeNutrition', () => {
  it('sums per-100 g values by grams and divides by servings', () => {
    const n = computeNutrition(
      { servings: 2, ingredients: [ingredient('lentil', 200, 'g'), ingredient('olive oil', 1, 'tbsp')] },
      new Map([
        ['lentil', lentil],
        ['olive oil', oil],
      ]),
    );
    // 200 g lentils = 704 kcal, 49.2 g protein; 1 tbsp oil = 13.8 g = 122 kcal.
    expect(n.total.kcal).toBe(826);
    expect(n.perServing).toMatchObject({ kcal: 413, protein: 24.6 });
    expect(n.completeness).toBe(1);
    expect(n.partial).toBe(false);
    expect(n).toMatchObject({ estimated: true, source: 'USDA FoodData Central', servings: 2 });
  });

  it('counts unmatched and unclear ingredients against completeness', () => {
    const n = computeNutrition(
      {
        servings: 2,
        ingredients: [ingredient('lentil', 200, 'g'), ingredient('mystery paste', 200, 'g'), ingredient('salt', null, null)],
      },
      new Map([['lentil', lentil]]),
    );
    // 200 resolved of 200 + 200 + a nominal 20 g for "salt, no amount".
    expect(n.completeness).toBe(0.48);
    expect(n.partial).toBe(true);
    expect(n.unresolved).toEqual(['mystery paste', 'salt']);
  });

  it('tracks completeness per nutrient when a food lacks one', () => {
    const noSugar = food(3, { kcal: 40, protein: 1, fat: 0, saturatedFat: 0, carbs: 9, fiber: 2, sodium: 4 });
    const n = computeNutrition(
      { servings: 1, ingredients: [ingredient('lentil', 100, 'g'), ingredient('onion', 300, 'g')] },
      new Map([
        ['lentil', lentil],
        ['onion', noSugar],
      ]),
    );
    expect(n.nutrientCompleteness.sugar).toBe(0.25);
    expect(n.nutrientCompleteness.protein).toBe(1);
  });

  it('gives no per-serving figure when servings are unknown', () => {
    const n = computeNutrition({ ingredients: [ingredient('lentil', 100, 'g')] }, new Map([['lentil', lentil]]));
    expect(n.perServing).toBeNull();
    expect(n.total.kcal).toBe(352);
  });

  it('keys canned products separately from dry ones', () => {
    expect(mappingKey(ingredient('chickpeas', 1, 'can'))).toBe('chickpea|canned');
    expect(mappingKey(ingredient('chickpea', 200, 'g', { rawText: '200 g canned chickpeas' }))).toBe('chickpea|canned');
    expect(mappingKey(ingredient('chickpea', 200, 'g'))).toBe('chickpea');
  });
});

import { analysis, ingredient } from '../../test/fixtures/analysis';
import { matchGoals } from '../meal-plan/profile-fit';
import { NutrientTotals, NutritionResult } from './nutrition';
import { nutritionFacts } from './nutrition-facts';

function nutrition(perServing: Partial<NutrientTotals>, overrides: Partial<NutritionResult> = {}): NutritionResult {
  const totals: NutrientTotals = { kcal: 500, protein: 10, fat: 10, saturatedFat: 2, carbs: 60, sugar: 5, fiber: 4, sodium: 800, ...perServing };
  const full = { kcal: 1, protein: 1, fat: 1, saturatedFat: 1, carbs: 1, sugar: 1, fiber: 1, sodium: 1 };
  return {
    perServing: totals,
    total: totals,
    servings: 1,
    completeness: 0.9,
    nutrientCompleteness: full,
    partial: false,
    unresolved: [],
    estimated: true,
    source: 'USDA FoodData Central',
    version: 1,
    ...overrides,
  };
}

describe('nutritionFacts', () => {
  it.each([
    [{ protein: 20 }, 'high-protein'],
    [{ sodium: 600 }, 'low-sodium'],
    [{ sodium: 1000 }, 'moderate-sodium'],
    [{ fiber: 8 }, 'high-fiber'],
    [{ carbs: 30 }, 'low-carb'],
    [{ sugar: 10 }, 'low-sugar'],
  ])('%o per serving -> %s', (perServing, signal) => {
    expect(nutritionFacts(analysis({ nutrition: nutrition(perServing) })).signals).toContain(signal);
  });

  it('replaces the model nutrient labels in restriction tags with computed ones', () => {
    const facts = nutritionFacts(
      analysis({ restrictionTags: ['vegan', 'low-sodium'], nutritionSignals: ['high-protein'], nutrition: nutrition({}) }),
    );
    expect(facts.basis).toBe('nutrients');
    expect(facts.tags).toEqual(['vegan']); // 800 mg sodium is moderate, not low
    expect(facts.signals).toContain('moderate-sodium');
    expect(facts.signals).not.toContain('high-protein');
  });

  it('adds prep-time and whole-food labels from the recipe itself', () => {
    const facts = nutritionFacts(
      analysis({ prepMinutes: 25, ingredients: [ingredient('lentil', 200, 'g')], nutrition: nutrition({}) }),
    );
    expect(facts.signals).toEqual(expect.arrayContaining(['quick-prep', 'whole-foods']));
  });

  it('falls back to model labels when nutrients are partial or missing', () => {
    const partial = nutritionFacts(
      analysis({ nutritionSignals: ['high-protein'], nutrition: nutrition({ protein: 40 }, { completeness: 0.5, partial: true }) }),
    );
    expect(partial).toMatchObject({ basis: 'model', signals: ['high-protein'], perServing: null });
    expect(nutritionFacts(analysis({ nutritionSignals: [] })).basis).toBe('none');
  });

  it('never labels a nutrient that most of the recipe did not report', () => {
    const facts = nutritionFacts(
      analysis({ nutrition: nutrition({ sugar: 1 }, { nutrientCompleteness: { ...nutrition({}).nutrientCompleteness, sugar: 0.4 } }) }),
    );
    expect(facts.signals).not.toContain('low-sugar');
    expect(facts.covers('low-sugar')).toBe(false);
  });
});

describe('matchGoals with computed nutrients', () => {
  it('matches, misses, or cannot verify each goal', () => {
    const a = analysis({
      nutrition: nutrition({ protein: 30, sodium: 900 }, { nutrientCompleteness: { ...nutrition({}).nutrientCompleteness, sugar: 0.2 } }),
    });
    expect(matchGoals(a, ['high-protein', 'low-sodium', 'low-sugar', 'weight-loss'])).toEqual({
      matched: ['high-protein'],
      missing: ['low-sodium'],
      unverifiable: ['low-sugar', 'weight-loss'],
    });
  });

  it('cannot verify nutrient goals without any nutrient basis', () => {
    expect(matchGoals(analysis({ nutritionSignals: [] }), ['high-protein']).unverifiable).toEqual(['high-protein']);
  });
});

import { analysis, ingredient } from '../../test/fixtures/analysis';
import { FdcFood } from './fdc-food';
import { FdcMapping, FdcMappingStore } from './fdc-mapping.store';
import { FdcClient } from './fdc.client';
import { NutritionService } from './nutrition.service';

const lentils: FdcFood = {
  fdcId: 172420,
  description: 'Lentils, raw',
  dataType: 'SR Legacy',
  nutrients: { kcal: 352, protein: 24.6, fat: 1.1, saturatedFat: 0.2, carbs: 63.4, sugar: 2, fiber: 10.7, sodium: 6 },
  portions: [],
};
const coconutMilk: FdcFood = { ...lentils, fdcId: 999, description: 'Nuts, coconut milk, canned' };

class FakeFdc implements FdcClient {
  enabled = true;
  searches: string[] = [];
  down = false;
  async search(query: string): Promise<FdcFood[]> {
    this.searches.push(query);
    if (this.down) throw new Error('FDC request failed (503)');
    return query.startsWith('lentil') ? [{ ...lentils, portions: [] }] : [];
  }
  async foods(ids: number[]): Promise<FdcFood[]> {
    return ids.map((id) => (id === 999 ? coconutMilk : lentils));
  }
}

class MemoryStore implements FdcMappingStore {
  entries = new Map<string, FdcMapping>();
  async get(key: string) {
    return this.entries.get(key) ?? null;
  }
  async set(m: FdcMapping) {
    this.entries.set(m.key, m);
  }
}

describe('NutritionService', () => {
  const soup = () =>
    analysis({
      servings: 2,
      ingredients: [
        ingredient('lentil', 200, 'g'),
        ingredient('coconut milk', 200, 'g'),
        ingredient('olive oil', 1, 'tbsp', { confidence: 'low' }),
      ],
    });

  it('computes nutrients, uses overrides and caches mappings for every video', async () => {
    const fdc = new FakeFdc();
    const store = new MemoryStore();
    const svc = new NutritionService(fdc, store, { 'coconut milk': { fdcId: 999 } });

    const first = await svc.ensure(soup());
    expect(first.nutrition?.perServing?.protein).toBeCloseTo(49.2);
    expect(fdc.searches).toEqual(['lentil']); // override needs no search; low confidence needs no lookup
    expect(store.entries.get('coconut milk')?.food?.fdcId).toBe(999);

    await svc.ensure(soup());
    expect(fdc.searches).toEqual(['lentil']);
  });

  it('remembers ingredients with no match', async () => {
    const fdc = new FakeFdc();
    const svc = new NutritionService(fdc, new MemoryStore(), {});
    const a = analysis({ ingredients: [ingredient('unobtainium', 100, 'g')] });
    expect((await svc.ensure(a)).nutrition?.unresolved).toEqual(['unobtainium']);
    await svc.ensure(a);
    expect(fdc.searches).toEqual(['unobtainium']);
  });

  it('returns the analysis with nutrition null when FDC is down', async () => {
    const fdc = new FakeFdc();
    fdc.down = true;
    const out = await new NutritionService(fdc, new MemoryStore(), {}).ensure(soup());
    expect(out.nutrition).toBeNull();
    expect(out.ingredients).toHaveLength(3);
  });

  it('does nothing without an FDC key or for current nutrients', async () => {
    const fdc = new FakeFdc();
    fdc.enabled = false;
    const a = soup();
    expect(await new NutritionService(fdc, new MemoryStore(), {}).ensure(a)).toBe(a);

    fdc.enabled = true;
    const svc = new NutritionService(fdc, new MemoryStore(), { 'coconut milk': { fdcId: 999 } });
    const done = await svc.ensure(a);
    expect(await svc.ensure(done)).toBe(done);
  });

  it('searches canned products as canned', async () => {
    const fdc = new FakeFdc();
    await new NutritionService(fdc, new MemoryStore(), {}).ensure(
      analysis({ ingredients: [ingredient('chickpea', 1, 'can')] }),
    );
    expect(fdc.searches).toEqual(['chickpea canned']);
  });
});

