import {
  CanActivate,
  ExecutionContext,
  Injectable,
  ServiceUnavailableException,
  SetMetadata,
  UnauthorizedException,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { createHash, timingSafeEqual } from 'crypto';
import { Request } from 'express';
import { AppConfigService } from '../config/app-config.service';

export const APP_KEY_HEADER = 'x-api-key';
const USER_SCOPED_BODY = 'appKey:userScopedBody';

/** Require the key only when the body names a user (it then reads stored health data). */
export const RequireAppKeyForUserBody = () => SetMetadata(USER_SCOPED_BODY, true);

function digest(value: string): Buffer {
  return createHash('sha256').update(value).digest();
}

/**
 * The JJFit app owns identity and calls this service with a shared key
 * (MEALPILOT_APP_KEY). Without a configured key the user-data endpoints are
 * open in development and refused in production.
 */
@Injectable()
export class AppKeyGuard implements CanActivate {
  constructor(
    private readonly config: AppConfigService,
    private readonly reflector: Reflector,
  ) {}

  canActivate(context: ExecutionContext): boolean {
    const request = context.switchToHttp().getRequest<Request>();
    const userScoped = this.reflector.get<boolean>(USER_SCOPED_BODY, context.getHandler());
    if (userScoped && !(request.body as { userId?: unknown } | undefined)?.userId) return true;

    const expected = this.config.appKey;
    if (!expected) {
      if (this.config.nodeEnv === 'production') {
        throw new ServiceUnavailableException('User data endpoints are disabled: MEALPILOT_APP_KEY is not configured');
      }
      return true;
    }

    const sent = request.headers[APP_KEY_HEADER];
    // Compare digests so length differences don't leak through timing.
    if (typeof sent === 'string' && timingSafeEqual(digest(sent), digest(expected))) return true;
    throw new UnauthorizedException('Missing or invalid x-api-key');
  }
}

import { ApiProperty, ApiPropertyOptional } from '@nestjs/swagger';
import {
  ArrayMaxSize,
  Equals,
  IsArray,
  IsBoolean,
  IsInt,
  IsOptional,
  IsString,
  Max,
  MaxLength,
  Min,
} from 'class-validator';
import { ProfileFieldsDto } from '../../meal-plan/dto/profile-fields.dto';

export class ProfileDto extends ProfileFieldsDto {
  @ApiProperty({
    description:
      'Explicit consent to store this health profile (GDPR Art. 9). Must be true; the time of consent is recorded.',
    enum: [true],
  })
  @IsBoolean()
  @Equals(true, { message: 'consent must be true to store a health profile' })
  consent!: true;
}

export class MealLogDto {
  @ApiProperty({ example: 'jfKL8pQjBCA' })
  @IsString()
  @MaxLength(64)
  videoId!: string;

  @ApiPropertyOptional()
  @IsOptional()
  @IsString()
  @MaxLength(64)
  planId?: string;

  @ApiProperty({ description: 'Whether the user cooked it.' })
  @IsBoolean()
  cooked!: boolean;

  @ApiPropertyOptional({
    minimum: 1,
    maximum: 5,
    description: 'Rated 1: never recommended again. 2 or lower: the agent avoids it. 4-5: brought back now and then.',
  })
  @IsOptional()
  @IsInt()
  @Min(1)
  @Max(5)
  rating?: number;

  @ApiPropertyOptional({ maxLength: 500 })
  @IsOptional()
  @IsString()
  @MaxLength(500)
  note?: string;
}

export class CheckedItemsDto {
  @ApiProperty({ type: [String], example: ['chickpea|g', 'spring onion|bunch'], description: 'Shopping-list item keys that are ticked.' })
  @IsArray()
  @ArrayMaxSize(300)
  @IsString({ each: true })
  @MaxLength(200, { each: true })
  checked!: string[];
}

export class SwapMealDto {
  @ApiProperty({ description: 'The recipe in the plan to replace.', example: 'jfKL8pQjBCA' })
  @IsString()
  @MaxLength(64)
  videoId!: string;
}

import { Inject, Injectable, NotFoundException } from '@nestjs/common';
import { randomUUID } from 'crypto';
import { MealPlanRequestDto } from '../meal-plan/dto/meal-plan-request.dto';
import { FeedbackMap, feedbackFrom } from './feedback';
import { MealLogDto, ProfileDto } from './dto/user-data.dto';
import {
  DeletedUserData,
  MealLog,
  ProfileData,
  StoredProfile,
  USER_DATA_STORE,
  UserDataStore,
} from './user-data.store';

/** Fields a stored profile holds; inline request values override them one by one. */
const PROFILE_FIELDS = [
  'healthProfile',
  'bloodPressure',
  'restrictions',
  'allergies',
  'healthGoals',
  'householdSize',
  'maxCookMinutes',
  'budget',
  'preferences',
] as const satisfies ReadonlyArray<keyof ProfileData>;

export function pickProfile(source: Partial<ProfileData>): ProfileData {
  const out: Record<string, unknown> = {};
  for (const f of PROFILE_FIELDS) {
    if (source[f] !== undefined) out[f] = source[f];
  }
  return out as ProfileData;
}

export interface ResolvedRequest {
  request: MealPlanRequestDto;
  feedback: FeedbackMap;
}

@Injectable()
export class ProfilesService {
  constructor(@Inject(USER_DATA_STORE) private readonly store: UserDataStore) {}

  async get(userId: string): Promise<StoredProfile> {
    const profile = await this.store.getProfile(userId);
    if (!profile) throw new NotFoundException('No stored profile for this user');
    return profile;
  }

  async put(userId: string, dto: ProfileDto): Promise<StoredProfile> {
    const now = new Date().toISOString();
    const existing = await this.store.getProfile(userId);
    const stored: StoredProfile = {
      userId,
      profile: pickProfile(dto),
      consentAt: now,
      createdAt: existing?.createdAt ?? now,
      updatedAt: now,
    };
    await this.store.putProfile(stored);
    return stored;
  }

  delete(userId: string): Promise<DeletedUserData> {
    return this.store.deleteUser(userId);
  }

  /**
   * The profile a plan is built for: the stored one, with any field sent
   * inline taking precedence. An unknown userId is an error rather than an
   * empty profile, so a typo can never drop the user's allergies.
   */
  async resolve(dto: MealPlanRequestDto): Promise<ResolvedRequest> {
    if (!dto.userId) return { request: dto, feedback: new Map() };
    const stored = await this.get(dto.userId);
    const request: MealPlanRequestDto = { ...stored.profile, ...stripUndefined(dto) };
    return { request, feedback: await this.feedback(dto.userId) };
  }

  async feedback(userId: string): Promise<FeedbackMap> {
    return feedbackFrom(await this.store.listMeals(userId));
  }

  async addMeal(userId: string, dto: MealLogDto): Promise<MealLog> {
    const log: MealLog = {
      id: randomUUID(),
      userId,
      videoId: dto.videoId,
      planId: dto.planId ?? null,
      cooked: dto.cooked,
      rating: dto.rating ?? null,
      note: dto.note ?? null,
      createdAt: new Date().toISOString(),
    };
    await this.store.addMeal(log);
    return log;
  }

  listMeals(userId: string): Promise<MealLog[]> {
    return this.store.listMeals(userId);
  }
}

function stripUndefined<T extends object>(value: T): Partial<T> {
  return Object.fromEntries(Object.entries(value).filter(([, v]) => v !== undefined)) as Partial<T>;
}

